const fs = require('fs');
const readline = require('readline');
const path = require('path');

const logFilePath = 'C:\\Users\\admin\\.gemini\\antigravity-ide\\brain\\53b57104-e4e2-40d0-adc5-813cc565893f\\.system_generated\\logs\\transcript_full.jsonl';

async function main() {
  if (!fs.existsSync(logFilePath)) {
    console.log('Log file does not exist:', logFilePath);
    return;
  }

  const fileStream = fs.createReadStream(logFilePath);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  let stepCount = 0;
  const toolCalls = [];

  for await (const line of rl) {
    stepCount++;
    try {
      const step = JSON.parse(line);
      // We look for steps of type PLANNER_RESPONSE or MODEL containing tool_calls
      if (step.tool_calls && step.tool_calls.length > 0) {
        for (const tc of step.tool_calls) {
          if (tc.name === 'write_to_file' || tc.name === 'replace_file_content' || tc.name === 'multi_replace_file_content') {
            toolCalls.push({
              step_index: step.step_index || stepCount,
              name: tc.name,
              args: tc.args
            });
          }
        }
      }
    } catch (err) {
      // ignore parse errors
    }
  }

  console.log(`Read ${stepCount} steps. Found ${toolCalls.length} file-modifying tool calls.`);

  // Group by TargetFile
  const filesMap = {};
  for (const tc of toolCalls) {
    const file = tc.args.TargetFile;
    if (!file) continue;
    if (!filesMap[file]) {
      filesMap[file] = [];
    }
    filesMap[file].push(tc);
  }

  for (const file of Object.keys(filesMap)) {
    console.log(`\n=== File: ${file} (count: ${filesMap[file].length}) ===`);
    // Print the step indices of edits
    console.log('Steps:', filesMap[file].map(tc => `${tc.step_index} (${tc.name})`).join(', '));

    // Save the list of edits to a file for detailed inspection
    const baseName = path.basename(file);
    const dumpPath = path.join(__dirname, `edits-${baseName}.json`);
    fs.writeFileSync(dumpPath, JSON.stringify(filesMap[file], null, 2));
    console.log(`Saved detailed edits history to ${dumpPath}`);
  }
}

main().catch(console.error);
